111:    /* Not Recently Used with a second chance: sweep the frames, give every
112:     * page whose accessed bit is set one more round (clearing the bit as we
113:     * pass by), and evict the first one that survived a whole sweep unused.
114:     * Pinned frames (kernel stacks, shared pages) and frames that are not
115:     * reachable through a page table entry can never be evicted. */
116:    static int clock_hand = 0;
117:
118:    for(int step = 0; step < 2 * USER_PAGE_NUM; step++){
119:        int i = clock_hand;
120:        clock_hand = (clock_hand + 1) % USER_PAGE_NUM;
121:
122:        if(!user_page[i].valid || user_page[i].pin || user_page[i].pgtable == NULL){
123:            continue;
124:        }
125:        if(get_attribute(*user_page[i].pgtable, _PAGE_ACCESSED)){
126:            clear_attribute(user_page[i].pgtable, _PAGE_ACCESSED);
127:            continue;
128:        }
129:        return num2pa(i);
130:    }
131:
132:    /* every single frame is pinned, there is nothing we can do */
133:    assert(0);
134:    return 0;
135:}
